CREATE TABLE users(id text PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL,display_name text,locale text NOT NULL DEFAULT 'en',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deletion_requested')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_accounts(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),provider text NOT NULL,provider_account_id text NOT NULL,UNIQUE(provider,provider_account_id));
CREATE TABLE auth_sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),csrf_token text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_sessions_user ON auth_sessions(user_id);
CREATE TABLE auth_attempts(bucket text PRIMARY KEY,count integer NOT NULL CHECK(count>=0),window_start timestamptz NOT NULL);
CREATE TABLE account_deletion_requests(id text PRIMARY KEY,user_id text NOT NULL UNIQUE REFERENCES users(id),requested_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processed','canceled')));
CREATE TABLE credit_wallets(user_id text PRIMARY KEY REFERENCES users(id),balance integer NOT NULL DEFAULT 0 CHECK(balance>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=balance),debt integer NOT NULL DEFAULT 0 CHECK(debt>=0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_packages(id text PRIMARY KEY,credits integer NOT NULL CHECK(credits>0),price_minor integer NOT NULL CHECK(price_minor>0),currency text NOT NULL,label text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE payment_orders(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),package_id text NOT NULL REFERENCES credit_packages(id),provider text NOT NULL,provider_checkout_id text,provider_payment_id text,amount_minor integer NOT NULL CHECK(amount_minor>0),currency text NOT NULL,credits integer NOT NULL CHECK(credits>0),idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','canceled','refunded','disputed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key),UNIQUE(provider,provider_payment_id));
CREATE TABLE payment_webhook_events(provider text NOT NULL,event_id text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','processed','failed')),error text,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(provider,event_id));
CREATE TABLE generation_jobs(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),request jsonb NOT NULL,input_hash text NOT NULL DEFAULT '',idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed')),credits integer NOT NULL CHECK(credits>0),cost_micros integer NOT NULL CHECK(cost_micros>0),budget_day date NOT NULL DEFAULT CURRENT_DATE,attempt integer NOT NULL DEFAULT 0 CHECK(attempt>=0),lease_token text,lease_owner text,lease_expires_at timestamptz,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(user_id,idempotency_key));
CREATE INDEX generation_jobs_claim ON generation_jobs(status,created_at);
CREATE TABLE generation_attempts(job_id text NOT NULL REFERENCES generation_jobs(id),attempt integer NOT NULL CHECK(attempt>0),lease_token text NOT NULL,status text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,PRIMARY KEY(job_id,attempt));
CREATE TABLE generation_budgets(day date NOT NULL,scope text NOT NULL,scope_id text NOT NULL,reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0),spent integer NOT NULL DEFAULT 0 CHECK(spent>=0),PRIMARY KEY(day,scope,scope_id));
CREATE TABLE generation_control(id integer PRIMARY KEY CHECK(id=1),paused boolean NOT NULL DEFAULT false);
INSERT INTO generation_control(id) VALUES(1);
CREATE TABLE image_assets(id text PRIMARY KEY,job_id text NOT NULL UNIQUE REFERENCES generation_jobs(id),user_id text NOT NULL REFERENCES users(id),storage_key text NOT NULL UNIQUE,mime text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_reservations(job_id text PRIMARY KEY REFERENCES generation_jobs(id),user_id text NOT NULL REFERENCES users(id),amount integer NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'held' CHECK(status IN ('held','captured','released')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_ledger(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),idempotency_key text NOT NULL,reason text NOT NULL,amount integer NOT NULL CHECK(amount>0),balance_delta integer NOT NULL,reserved_delta integer NOT NULL,debt_delta integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key),CHECK(balance_delta<>0 OR reserved_delta<>0 OR debt_delta<>0));
CREATE INDEX credit_ledger_user ON credit_ledger(user_id,created_at);
CREATE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'credit ledger is immutable'; END; $$;
CREATE TRIGGER credit_ledger_immutable BEFORE UPDATE OR DELETE ON credit_ledger FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
